package retry

import (
	"fmt"
	"time"
)

// BackoffStrategy defines how to calculate wait duration between retries
type BackoffStrategy func(attempt int) time.Duration

// LinearBackoff returns a linear backoff strategy
func LinearBackoff(baseDelay time.Duration) BackoffStrategy {
	return func(attempt int) time.Duration {
		return baseDelay * time.Duration(attempt)
	}
}

// ExponentialBackoff returns an exponential backoff strategy with jitter
func ExponentialBackoff(baseDelay time.Duration, maxDelay time.Duration) BackoffStrategy {
	return func(attempt int) time.Duration {
		delay := baseDelay * (1 << uint(attempt))
		if delay > maxDelay {
			delay = maxDelay
		}
		return delay
	}
}

// RetryConfig holds retry configuration
type RetryConfig struct {
	MaxAttempts int
	Backoff     BackoffStrategy
}

// ProcessItemWithRetry attempts to process an item with retry logic
func ProcessItemWithRetry(item interface{}, cfg RetryConfig) error {
	if cfg.MaxAttempts <= 0 {
		cfg.MaxAttempts = 3
	}
	if cfg.Backoff == nil {
		cfg.Backoff = LinearBackoff(100 * time.Millisecond)
	}

	var lastErr error

	for attempt := 0; attempt < cfg.MaxAttempts; attempt++ {
		// Attempt the operation
		err := processItem(item)
		if err == nil {
			return nil // Success
		}

		// Preserve error for final return
		lastErr = err

		// Don't sleep after the last failed attempt
		if attempt < cfg.MaxAttempts-1 {
			delay := cfg.Backoff(attempt + 1)
			time.Sleep(delay)
		}
	}

	// Return the last error with context
	return fmt.Errorf("failed to process item after %d attempts: %w", cfg.MaxAttempts, lastErr)
}

// ProcessItemsWithRetry processes multiple items with retry logic
// Returns a slice of errors (one per item), preserving order
func ProcessItemsWithRetry(items []interface{}, cfg RetryConfig) []error {
	if cfg.MaxAttempts <= 0 {
		cfg.MaxAttempts = 3
	}
	if cfg.Backoff == nil {
		cfg.Backoff = LinearBackoff(100 * time.Millisecond)
	}

	results := make([]error, len(items))

	for i, item := range items {
		results[i] = ProcessItemWithRetry(item, cfg)
	}

	return results
}

// processItem simulates the actual work (replace with real logic)
func processItem(item interface{}) error {
	// Implementation here
	return nil
}
```

