)

type User struct {
	ID    int
	Name  string
	Email string
}

var (
	userCache = cache.New(10 * time.Minute)
	database  = []User{
		{ID: 1, Name: "Alice", Email: "alice@example.com"},
		{ID: 2, Name: "Bob", Email: "bob@example.com"},
	}
