## Practical Examples

### Example 1: Basic Usage

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

func main() {
    // Create a cache with 5-minute TTL
    c := cache.New(5 * time.Minute)

    // Store values
    c.Set("greeting", "Hello, World!")
    c.Set("counter", 42)
    c.Set("pi", 3.14159)

    // Retrieve values
    if value, exists := c.Get("greeting"); exists {
        fmt.Println(value) // Output: Hello, World!
    }

    // Non-existent key
    if _, exists := c.Get("missing"); !exists {
        fmt.Println("Key not found")
    }
}
```

### Example 2: Cache-Aside Pattern (Lazy Loading)

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

type User struct {
    ID   int
    Name string
}

var c = cache.New(1 * time.Hour)

func GetUser(userID int) User {
    key := fmt.Sprintf("user:%d", userID)

    // Try to get from cache
    if cached, exists := c.Get(key); exists {
        return cached.(User)
    }

    // Cache miss - fetch from database
    user := fetchUserFromDatabase(userID)

    // Store in cache for future requests
    c.Set(key, user)

    return user
}

func fetchUserFromDatabase(id int) User {
    // Expensive database call
    return User{ID: id, Name: "John Doe"}
}
```

### Example 3: Concurrent Access

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "your-module/cache"
)

func main() {
    c := cache.New(10 * time.Minute)

    // Multiple goroutines writing concurrently
    var wg sync.WaitGroup
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            key := fmt.Sprintf("key:%d", id)
            c.Set(key, id*100)
        }(i)
    }

    // Multiple goroutines reading concurrently
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            key := fmt.Sprintf("key:%d", id)
            if value, exists := c.Get(key); exists {
                fmt.Printf("Got %v from cache\n", value)
            }
        }(i)
    }

    wg.Wait()
}
```

### Example 4: Session Management

