### Example 5: Cache Cleanup and Lifecycle Management

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

func main() {
    c := cache.New(1 * time.Hour)

    // Populate cache
    for i := 0; i < 100; i++ {
        c.Set(fmt.Sprintf("data:%d", i), i)
    }

    // Delete specific entries
    c.Delete("data:42")

    // Clear entire cache when needed (e.g., on restart, config change)
    c.Purge()

    // Cache is now empty and ready for reuse
    if _, exists := c.Get("data:0"); !exists {
        println("Cache cleared successfully")
    }
}
```

