## 6. Database Query Caching

```go
package main

import (
	"fmt"
	"time"
	"yourmodule/cache"
)

func queryDatabase(userID string) map[string]interface{} {
	// Simulate database query
	return map[string]interface{}{
		"id":    userID,
		"name":  "John Doe",
		"email": "john@example.com",
	}
}

func getUserWithCache(c *cache.Cache, userID string) map[string]interface{} {
	cacheKey := fmt.Sprintf("user:%s", userID)

	// Try cache first
	if cached, ok := c.Get(cacheKey); ok {
		fmt.Printf("Cache HIT for user %s\n", userID)
		return cached.(map[string]interface{})
	}

	// Cache miss: query database
	fmt.Printf("Cache MISS for user %s - querying database\n", userID)
	user := queryDatabase(userID)
	c.Set(cacheKey, user)

	return user
}

func main() {
	c := cache.New(10 * time.Minute)

	// First call - database hit
	user1 := getUserWithCache(c, "123")
	fmt.Printf("User: %s\n\n", user1["name"])

	// Second call - cache hit
	user2 := getUserWithCache(c, "123")
	fmt.Printf("User: %s\n\n", user2["name"])

	// Different user - database hit
	user3 := getUserWithCache(c, "456")
	fmt.Printf("User: %s\n", user3["name"])
}
```

