## Fix 2: Unrestricted File Upload (CWE-434) - HIGH

**Problem**: No validation of file type; dangerous executable files can be uploaded

**Fixed Code**:
```go
import (
    "mime"
    "net/http"
)

func isAllowedFileType(filename string, fileHeader *multipart.FileHeader, fileContent io.Reader) bool {
    // Whitelist allowed extensions
    allowedExts := map[string]bool{
        ".pdf":  true,
        ".doc":  true,
        ".docx": true,
        ".txt":  true,
        ".jpg":  true,
        ".png":  true,
    }

    // Check extension
    ext := strings.ToLower(filepath.Ext(filename))
    if !allowedExts[ext] {
        return false
    }

    // Check MIME type
    allowedMimeTypes := map[string]bool{
        "application/pdf":           true,
        "application/msword":        true,
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": true,
        "text/plain":                true,
        "image/jpeg":                true,
        "image/png":                 true,
    }

    if !allowedMimeTypes[fileHeader.Header.Get("Content-Type")] {
        return false
    }

    // Check magic bytes (first few bytes of file)
    magicBytes := make([]byte, 512)
    n, _ := fileContent.Read(magicBytes)
    detectedMime := http.DetectContentType(magicBytes[:n])

    if !allowedMimeTypes[detectedMime] {
        return false
    }

    return true
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
    file, header, _ := r.FormFile("document")
    defer file.Close()

    // Validate file type
    if !isAllowedFileType(header.Filename, header, file) {
        http.Error(w, "File type not allowed", http.StatusBadRequest)
        return
    }

    // Reset file pointer after validation
    file.Seek(0, 0)

    // ... rest of upload logic with path sanitization (Fix 1)
}
