// Property test helper: Verify output is sorted
func isSorted(arr []int) bool {
	for i := 1; i < len(arr); i++ {
		if arr[i] < arr[i-1] {
			return false
		}
	}
	return true
}

// Property test helper: Verify same elements exist in both arrays (same multiset)
func sameElements(original, sorted []int) bool {
	if len(original) != len(sorted) {
		return false
	}

	// Count occurrences in both arrays
	originalCount := make(map[int]int)
	for _, v := range original {
		originalCount[v]++
	}

	sortedCount := make(map[int]int)
	for _, v := range sorted {
		sortedCount[v]++
	}

	// Compare counts
	if len(originalCount) != len(sortedCount) {
		return false
	}

	for k, v := range originalCount {
		if sortedCount[k] != v {
			return false
		}
	}

	return true
}

